CHANNEL_ID = os.environ.get("CHANNEL_ID", "@ModernWarFarChannel")

def get_channel_id():
    try:
        import database as db
        db_val = db.get_setting("channel_id")
        if db_val:
            return db_val
    except Exception:
        pass
    return CHANNEL_ID

